// The document head of a site page: title, description, canonical, hreflang, Open Graph / Twitter,
// icons (generated by tools/brand under /site/), theme colour, the :root token <style> and JSON-LD.
// A robots noindex meta only on a noindex page and the Smart App Banner meta only once the App Store
// id is set.
import type { JSX } from 'react';
import { UI_COLORS } from '@pn/design-tokens';
import type { Locale } from '@pn/i18n';
import type { SiteTranslator } from '@pn/i18n/site';

import { APP_STORE_ID, SITE_LOCALES, SITE_ORIGIN } from './config';
import type { RenderContext, SitePageDef } from './pages';
import { themeStyle } from './theme';

// Open Graph uses language_TERRITORY; the es copy is Latin American.
const OG_LOCALES: Readonly<Record<Locale, string>> = Object.freeze({
  'en-GB': 'en_GB',
  es: 'es_LA',
  'pt-BR': 'pt_BR',
});

const OG_IMAGE = `${SITE_ORIGIN}/site/og-default.png`;

// A value can never close the <script>: every '<' becomes <.
function jsonLdText(value: object): string {
  return JSON.stringify(value).replace(/</g, '\\u003c');
}

export function Head(props: {
  t: SiteTranslator;
  ctx: RenderContext;
  page: SitePageDef;
  /** Test seam; production callers leave it out (APP_STORE_ID). */
  appStoreId?: string | null;
}): JSX.Element {
  const { t, ctx, page } = props;
  const appStoreId = props.appStoreId === undefined ? APP_STORE_ID : props.appStoreId;
  const title = t.t(page.titleKey);
  const description = t.t(page.descriptionKey);
  const canonical = ctx.absoluteUrl(page.id);
  const jsonLd = page.jsonLd?.(t, ctx) ?? [];
  return (
    <>
      <title>{title}</title>
      <meta name="description" content={description} />
      {page.noindex === true ? <meta name="robots" content="noindex" /> : null}
      <link rel="canonical" href={canonical} />
      {SITE_LOCALES.map((locale) => (
        <link
          key={locale}
          rel="alternate"
          hrefLang={locale}
          href={ctx.absoluteUrl(page.id, locale)}
        />
      ))}
      <link rel="alternate" hrefLang="x-default" href={ctx.absoluteUrl(page.id, 'en-GB')} />
      <meta property="og:type" content="website" />
      <meta property="og:site_name" content={t.t('site.meta.siteName')} />
      <meta property="og:title" content={title} />
      <meta property="og:description" content={description} />
      <meta property="og:url" content={canonical} />
      <meta property="og:image" content={OG_IMAGE} />
      <meta property="og:image:width" content="1200" />
      <meta property="og:image:height" content="630" />
      <meta property="og:image:alt" content={t.t('site.meta.ogImageAlt')} />
      <meta property="og:locale" content={OG_LOCALES[ctx.locale]} />
      {SITE_LOCALES.filter((locale) => locale !== ctx.locale).map((locale) => (
        <meta key={locale} property="og:locale:alternate" content={OG_LOCALES[locale]} />
      ))}
      <meta name="twitter:card" content="summary_large_image" />
      <link rel="icon" href="/site/favicon.svg" type="image/svg+xml" />
      <link rel="icon" href="/site/favicon-32.png" sizes="32x32" type="image/png" />
      <link rel="apple-touch-icon" href="/site/apple-touch-icon.png" />
      <meta name="theme-color" content={UI_COLORS.bg} />
      {appStoreId ? <meta name="apple-itunes-app" content={`app-id=${appStoreId}`} /> : null}
      <style dangerouslySetInnerHTML={{ __html: themeStyle() }} />
      {jsonLd.map((value, i) => (
        <script
          key={i}
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: jsonLdText(value) }}
        />
      ))}
    </>
  );
}
